            tool_approval_modes: HashMap::new(),
        },
    );
    let manager = Arc::new(manager);
    let cached_binding = capture_binding(&manager).await;
    assert_eq!(
        cached_binding
            .tools()
            .iter()
            .map(|tool| tool.callable_name.as_str())
