#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn configured_http_proxy_rejects_restricted_requests_before_http_io() -> Result<()> {
    use codex_exec_server::ExecServerError;
    use codex_exec_server::HttpClient;
    use codex_exec_server::HttpRedirectPolicy;
    use codex_exec_server::HttpRequestParams;
    use codex_exec_server::HttpRequestRestrictedParams;
    use codex_exec_server::RouteAwareHttpClient;
    use codex_http_client::HttpClientFactory;
    use codex_http_client::OutboundProxyPolicy;

    const CHILD: &str = "CODEX_MCP_RESTRICTED_PROXY_TEST_SUBPROCESS";
    const RESOURCE: &str = "CODEX_MCP_RESTRICTED_PROXY_TEST_RESOURCE_ORIGIN";
    const WITNESS: &str = "HEPTA_RESTRICTED_PROXY_NEGATIVE_PASS ";
    const TEST: &str = "suite::mcp_startup_refresh_http_proxy::configured_http_proxy_rejects_restricted_requests_before_http_io";

    if std::env::var_os(CHILD).is_none() {
        let destination = std::net::TcpListener::bind("127.0.0.1:0")?;
        let proxy = std::net::TcpListener::bind("127.0.0.1:0")?;
        destination.set_nonblocking(true)?;
        proxy.set_nonblocking(true)?;
        let resource_origin = format!("http://{}", destination.local_addr()?);
        let proxy_origin = format!("http://{}", proxy.local_addr()?);
        let mut command = Command::new(std::env::current_exe()?);
        command
            .arg("--exact")
            .arg(TEST)
            .arg("--nocapture")
            .kill_on_drop(true);
        for &key in codex_network_proxy::PROXY_ENV_KEYS {
            command.env_remove(key);
        }
        command
            .env(CHILD, "1")
            .env(RESOURCE, &resource_origin)
            .env("HTTP_PROXY", &proxy_origin)
            .env("http_proxy", &proxy_origin)
            .env("NO_PROXY", "")
            .env("no_proxy", "");
        let output = tokio::time::timeout(Duration::from_secs(20), command.output()).await??;
        assert!(
            output.status.success(),
            "restricted proxy refusal subprocess failed\nstdout:\n{}\nstderr:\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr),
        );
        let stdout = std::str::from_utf8(&output.stdout)?;
        let stderr = std::str::from_utf8(&output.stderr)?;
        let expected_witness = format!("{WITNESS}{resource_origin}");
        let witnesses = stdout
            .lines()
            .chain(stderr.lines())
            .filter(|line| line.starts_with(WITNESS))
            .collect::<Vec<_>>();
        assert_eq!(
            witnesses,
            vec![expected_witness.as_str()],
            "child must execute the exact rejection assertion once\nstdout:\n{stdout}\nstderr:\n{stderr}"
        );
        assert_eq!(
            stdout
                .lines()
                .filter(|line| *line == "running 1 test")
                .count(),
            1,
            "child must select exactly one test: {stdout}"
        );
        let summaries = stdout
            .lines()
            .filter(|line| line.starts_with("test result: "))
            .collect::<Vec<_>>();
        assert_eq!(
            summaries.len(),
            1,
            "child must emit one test summary: {stdout}"
        );
        assert!(
            summaries[0]
                .starts_with("test result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; ")
                && summaries[0].contains(" filtered out; finished in "),
            "child must report one actual pass and no ignored test: {stdout}"
        );
        for listener in [destination, proxy] {
            assert!(
                matches!(listener.accept(), Err(error) if error.kind() == std::io::ErrorKind::WouldBlock),
                "proxy refusal must occur before any destination or proxy HTTP connection"
            );
        }
        return Ok(());
    }

    let resource_origin = std::env::var(RESOURCE)?;
    let client =
        RouteAwareHttpClient::new(HttpClientFactory::new(OutboundProxyPolicy::ReqwestDefault));
    let result = tokio::time::timeout(
        Duration::from_secs(2),
        client.http_request_stream_restricted(HttpRequestRestrictedParams {
            request: HttpRequestParams {
                method: "GET".to_string(),
                url: format!("{resource_origin}/oauth-resource"),
                headers: Vec::new(),
                body: None,
                timeout_ms: Some(1000),
                redirect_policy: HttpRedirectPolicy::Stop,
                request_id: "restricted-proxy-negative".to_string(),
                stream_response: true,
            },
            configured_resource_origin: resource_origin.clone(),
            authorization_origins: Default::default(),
        }),
    )
    .await?;
    let error = result
        .err()
        .expect("an active ordinary proxy must reject restricted HTTP");
    assert!(
        matches!(
            &error,
            ExecServerError::HttpRequest(message)
                if message == "http/request failed: the selected proxy does not support restricted HTTP destination enforcement"
        ),
        "unexpected restricted proxy error: {error:?}"
    );
    // A fresh, origin-bound witness appears only after the exact error assertion.
    println!("\n{WITNESS}{resource_origin}");
    Ok(())
}

#[must_use = "finish the proxy observation with assert_unused"]
struct UnexpectedOAuthProxy {
    uri: String,
    stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
    observer: Option<std::thread::JoinHandle<std::io::Result<Vec<String>>>>,
}

impl UnexpectedOAuthProxy {
    fn start() -> Result<Self> {
        let listener = std::net::TcpListener::bind("127.0.0.1:0")?;
        listener.set_nonblocking(true)?;
        let uri = format!("http://{}", listener.local_addr()?);
        let stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let observer_stop = std::sync::Arc::clone(&stop);
        let observer = std::thread::spawn(move || -> std::io::Result<Vec<String>> {
            let mut connections = Vec::new();
            loop {
                match listener.accept() {
                    Ok((stream, peer)) => {
                        // Observe at most one immediately available request-line prefix.
                        // Never wait for request bytes or let unexpected traffic hang.
                        stream.set_nonblocking(true)?;
                        let mut bytes = [0_u8; 256];
                        let prefix = match stream.peek(&mut bytes) {
                            Ok(count) => format!(
                                "first request-line prefix {:?}",
                                String::from_utf8_lossy(&bytes[..count])
                                    .lines()
                                    .next()
                                    .map(str::to_owned)
                            ),
                            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                                "no request bytes immediately available".to_string()
                            }
                            Err(error) => format!("request prefix peek failed: {error}"),
                        };
                        drop(stream);
                        connections.push(format!("{peer}: {prefix}"));
                        if connections.len() >= 16 {
                            return Err(std::io::Error::other(format!(
                                "unexpected OAuth proxy connection limit reached: {connections:?}"
                            )));
                        }
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        if observer_stop.load(std::sync::atomic::Ordering::Acquire) {
                            return Ok(connections);
                        }
                        std::thread::sleep(std::time::Duration::from_millis(5));
                    }
                    Err(error) => return Err(error),
                }
            }
        });
        Ok(Self {
            uri,
            stop,
            observer: Some(observer),
        })
    }

    fn uri(&self) -> &str {
        &self.uri
    }

    fn assert_unused(mut self) -> Result<()> {
        self.stop.store(true, std::sync::atomic::Ordering::Release);
        let connections = self
            .observer
            .take()
            .expect("proxy observer must be owned")
            .join()
            .expect("proxy observer must not panic")?;
        assert!(
            connections.is_empty(),
            "the explicit direct route unexpectedly reached its configured proxy: {connections:?}"
        );
        Ok(())
    }
}

impl Drop for UnexpectedOAuthProxy {
    fn drop(&mut self) {
        // Early test failures still close the listener and join the bounded observer.
        self.stop.store(true, std::sync::atomic::Ordering::Release);
        if let Some(observer) = self.observer.take() {
            let _ = observer.join();
        }
    }
}

codex-rs/rmcp-client/src/http_client_red.content:
//! Restricts MCP HTTP redirects to the configured server's origin.
//!
//! MCP requests can carry sensitive headers and tool-call bodies. Following a
//! cross-origin redirect would send them to another server or an internal
//! service, so this transport validates each redirect before following it.

use std::sync::Arc;
use std::time::Duration;
use std::time::Instant;

use codex_exec_server::ExecServerError;
use codex_exec_server::HttpClient;
use codex_exec_server::HttpHeader;
use codex_exec_server::HttpRedirectPolicy;
use codex_exec_server::HttpRequestParams;
use codex_exec_server::HttpRequestResponse;
use codex_exec_server::HttpRequestRestrictedParams;
use codex_exec_server::HttpResponseBodyStream;
use futures::FutureExt;
use futures::future::BoxFuture;
use http::HeaderValue;
use http::StatusCode;
use url::Url;

const MAX_REDIRECTS: usize = 10;

pub(crate) struct SameOriginRedirectHttpClient {
    inner: Arc<dyn HttpClient>,
}

enum RedirectResponse {
    Buffered(HttpRequestResponse),
    Streaming(HttpRequestResponse, HttpResponseBodyStream),
}

enum HttpRequestAccess {
    Ordinary,
    Restricted {
        configured_resource_origin: String,
        authorization_origins: codex_protocol::OAuthAuthorizationOrigins,
    },
}

impl SameOriginRedirectHttpClient {
    pub(crate) fn new(inner: Arc<dyn HttpClient>) -> Self {
        Self { inner }
    }

    async fn execute(
        &self,
        mut params: HttpRequestParams,
        access: HttpRequestAccess,
    ) -> Result<RedirectResponse, ExecServerError> {
        // Inspect each Location ourselves before the underlying client can send
        // sensitive request data to the redirect destination.
        params.redirect_policy = HttpRedirectPolicy::Stop;
        let mut current_url = Url::parse(&params.url)
            .map_err(|error| ExecServerError::HttpRequest(error.to_string()))?;
        let original_origin = current_url.origin();
        // Redirect hops share the original timeout instead of restarting it.
        let deadline = params
            .timeout_ms
            .map(|timeout_ms| Instant::now() + Duration::from_millis(timeout_ms));
        let mut redirects = 0;

        loop {
            if let Some(deadline) = deadline {
                let Some(remaining) = deadline.checked_duration_since(Instant::now()) else {
                    return Err(ExecServerError::HttpRequest(
                        "MCP HTTP request timed out".to_string(),
                    ));
                };
                params.timeout_ms = Some(
                    u64::try_from(remaining.as_millis())
                        .unwrap_or(u64::MAX)
                        .max(1),
                );
            }

            let result = match &access {
                HttpRequestAccess::Restricted {
                    configured_resource_origin,
                    authorization_origins,
                } => {
                    let (response, stream) = self
                        .inner
                        .http_request_stream_restricted(HttpRequestRestrictedParams {
                            request: params.clone(),
                            configured_resource_origin: configured_resource_origin.clone(),
                            authorization_origins: authorization_origins.clone(),
                        })
                        .await?;
                    RedirectResponse::Streaming(response, stream)
                }
                HttpRequestAccess::Ordinary if params.stream_response => {
                    let (response, stream) = self.inner.http_request_stream(params.clone()).await?;
                    RedirectResponse::Streaming(response, stream)
                }
                HttpRequestAccess::Ordinary => {
                    RedirectResponse::Buffered(self.inner.http_request(params.clone()).await?)
                }
            };
            let response = match &result {
                RedirectResponse::Buffered(response) | RedirectResponse::Streaming(response, _) => {
                    response
                }
            };
            let status = StatusCode::from_u16(response.status).ok();
            if !matches!(
                status,
                Some(
                    StatusCode::MOVED_PERMANENTLY
                        | StatusCode::FOUND
                        | StatusCode::SEE_OTHER
                        | StatusCode::TEMPORARY_REDIRECT
                        | StatusCode::PERMANENT_REDIRECT
                )
            ) {
                return Ok(result);
            }

            let Some(location) = response
                .headers
                .iter()
                .find(|header| header.name.eq_ignore_ascii_case("location"))
                .map(|header| header.value.as_str())
            else {
                return Ok(result);
            };
            let next_url = current_url
                .join(location)
                .map_err(|error| ExecServerError::HttpRequest(error.to_string()))?;
            // Compare every hop with the configured origin so redirect chains
            // cannot escape it through a later cross-origin Location.
            if next_url.origin() != original_origin {
                return Err(ExecServerError::HttpRequest(
                    "MCP HTTP redirect to a different origin is not allowed".to_string(),
                ));
            }
            // A hostname can resolve to a different address on the next HTTP
            // connection. HTTPS authenticates the hostname; localhost and IP
            // literals do not depend on attacker-controlled DNS.
            if next_url.scheme() == "http"
                && matches!(next_url.host(), Some(url::Host::Domain(host)) if host != "localhost")
            {
                return Err(ExecServerError::HttpRequest(
                    "MCP HTTP redirects for non-loopback hostnames require HTTPS".to_string(),
                ));
            }
            if redirects >= MAX_REDIRECTS {
                return Err(ExecServerError::HttpRequest(
                    "MCP HTTP request exceeded the redirect limit".to_string(),
                ));
            }

            // Preserve normal HTTP behavior: 307/308 retain the method and body;
            // 303 and legacy 301/302 POST redirects switch to a bodyless GET.
            let drop_body = matches!(
                status,
                Some(StatusCode::MOVED_PERMANENTLY | StatusCode::FOUND)
            ) && params.method.eq_ignore_ascii_case("POST")
                || status == Some(StatusCode::SEE_OTHER);
            if drop_body {
                if !params.method.eq_ignore_ascii_case("HEAD") {
                    params.method = "GET".to_string();
                }
                params.body = None;
                params.headers.retain(|header| {
                    ![
                        "content-type",
                        "content-length",
                        "content-encoding",
                        "transfer-encoding",
                    ]
                    .iter()
                    .any(|name| header.name.eq_ignore_ascii_case(name))
                });
            }

            // HTTPS keeps application proxy credentials inside the tunnel to
            // the already-validated origin. Plaintext routes can change across
            // requests, so their proxy credentials must never be replayed.
            params.headers.retain(|header| {
                (current_url.scheme() == "https"
                    || !header.name.eq_ignore_ascii_case("proxy-authorization"))
                    && !header.name.eq_ignore_ascii_case("referer")
            });
            let mut referer = current_url.clone();
            let _ = referer.set_username("");
            let _ = referer.set_password(None);
            referer.set_fragment(None);
            if HeaderValue::from_str(referer.as_str()).is_ok() {
                params.headers.push(HttpHeader {
                    name: "referer".to_string(),
                    value: referer.to_string(),
                    value_env_var: None,
                });
            }

            params.url = next_url.to_string();
            current_url = next_url;
            redirects += 1;
        }
    }
}

impl HttpClient for SameOriginRedirectHttpClient {
    fn restricted_request_cancellation(&self) -> Option<tokio_util::sync::CancellationToken> {
        self.inner.restricted_request_cancellation()
    }

    fn http_request_stream_restricted(
        &self,
        mut params: HttpRequestRestrictedParams,
    ) -> BoxFuture<'_, Result<(HttpRequestResponse, HttpResponseBodyStream), ExecServerError>> {
        async move {
            params.request.stream_response = true;
            if params.request.redirect_policy == HttpRedirectPolicy::Stop {
                return self.inner.http_request_stream_restricted(params).await;
            }
            match self
                .execute(
                    params.request,
                    HttpRequestAccess::Restricted {
                        configured_resource_origin: params.configured_resource_origin,
                        authorization_origins: params.authorization_origins,
                    },
                )
                .await?
            {
                RedirectResponse::Streaming(response, stream) => Ok((response, stream)),
                RedirectResponse::Buffered(_) => Err(ExecServerError::Protocol(
                    "MCP restricted HTTP request returned a buffered response".to_string(),
                )),
            }
        }
        .boxed()
    }

    fn supports_single_attempt_requests(&self) -> bool {
        self.inner.supports_single_attempt_requests()
    }

    fn http_request_stream_once(
        &self,
        params: HttpRequestParams,
    ) -> BoxFuture<'_, Result<(HttpRequestResponse, HttpResponseBodyStream), ExecServerError>> {
        // Do not enter execute(): even a same-origin redirect would replay a POST.
        self.inner.http_request_stream_once(params)
    }

    fn http_request(
        &self,
        mut params: HttpRequestParams,
    ) -> BoxFuture<'_, Result<HttpRequestResponse, ExecServerError>> {
        async move {
            params.stream_response = false;
            if params.redirect_policy == HttpRedirectPolicy::Stop {
                return self.inner.http_request(params).await;
            }
            match self.execute(params, HttpRequestAccess::Ordinary).await? {
                RedirectResponse::Buffered(response) => Ok(response),
                RedirectResponse::Streaming(_, _) => Err(ExecServerError::Protocol(
                    "MCP buffered HTTP request returned a streamed response".to_string(),
                )),
            }
        }
        .boxed()
    }

    fn http_request_stream(
        &self,
        mut params: HttpRequestParams,
    ) -> BoxFuture<'_, Result<(HttpRequestResponse, HttpResponseBodyStream), ExecServerError>> {
        async move {
            params.stream_response = true;
            if params.redirect_policy == HttpRedirectPolicy::Stop {
                return self.inner.http_request_stream(params).await;
            }
            match self.execute(params, HttpRequestAccess::Ordinary).await? {
                RedirectResponse::Streaming(response, stream) => Ok((response, stream)),
                RedirectResponse::Buffered(_) => Err(ExecServerError::Protocol(
                    "MCP streamed HTTP request returned a buffered response".to_string(),
                )),
            }
        }
        .boxed()
    }
}

